import MaintenanceNotice from '../../src/components/MaintenanceNotice.jsx';
import React from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter,Routes,Route} from 'react-router-dom';import AddCase from '../../src/pages/AddCasePage.jsx';import EditCase from '../../src/pages/EditCasePage.jsx';import Cases from '../../src/pages/ManageCasesPage.jsx';import AddClient from '../../src/pages/AddClientPage.jsx';import Clients from '../../src/pages/ManageClientsPage.jsx';import Csv from '../../src/pages/CsvCaseManager.jsx';import {tenantFetch} from '../../src/components/tenantFetch.js';
const root=createRoot(document.getElementById('root')),results=[];const check=(name,pass)=>results.push({name,pass:!!pass});const sleep=ms=>new Promise(r=>setTimeout(r,ms));const wait=async fn=>{const end=Date.now()+8000;while(Date.now()<end){if(fn())return;await sleep(30)}throw Error('wait timeout')};window.alert=()=>{};window.confirm=()=>true;
const A='000000000000000000000001';localStorage.setItem('userId',A);localStorage.setItem('user',JSON.stringify({_id:A}));sessionStorage.setItem('tnt_draft_session','a'.repeat(64));
const mount=path=>root.render(<MemoryRouter key={path} initialEntries={[path]}><Routes><Route path='/add' element={<AddCase/>}/><Route path='/case/edit/:id' element={<EditCase/>}/><Route path='/manage-cases' element={<Cases/>}/><Route path='/client-add' element={<AddClient/>}/><Route path='/manage-clients' element={<Clients/>}/><Route path='/csv' element={<Csv/>}/><Route path='/maintenance' element={<MaintenanceNotice feature='Payment book'/>}/></Routes></MemoryRouter>);
const set=(name,value)=>{const el=document.querySelector('[name="'+name+'"]');Object.getOwnPropertyDescriptor(el instanceof HTMLTextAreaElement?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));};const submit=async()=>{await sleep(40);document.querySelector('form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));};
(async()=>{try{
mount('/add');await wait(()=>document.querySelector('[name=caseName]'));set('caseName','BrowserCase');set('courtName','BrowserCourt');set('hearingDate','2026-11-13');await submit();await wait(()=>document.body.textContent.includes('BrowserCase')&&!document.querySelector('form'));check('real add/list cases uses verified session and excludes other owner',!document.body.textContent.includes('OtherPrivateCase'));
const rows=(await(await tenantFetch('/api/cases/user/'+A)).json()).cases;const id=rows.find(c=>c.caseName==='BrowserCase')._id;mount('/case/edit/'+id);await wait(()=>document.querySelector('[name=caseName]')?.value==='BrowserCase');set('caseName','BrowserEdited');await submit();await wait(()=>document.body.textContent.includes('BrowserEdited')&&!document.querySelector('form'));check('real edit case saves without replacing ownership',true);
mount('/client-add');await wait(()=>document.querySelector('[name=name]'));set('name','BrowserClient');set('phone','0000000000');await submit();await wait(()=>document.body.textContent.includes('BrowserClient')&&!document.querySelector('form'));check('real add/list clients preserves contract and owner isolation',!document.body.textContent.includes('OtherPrivateClient'));
const report=await tenantFetch('/api/reports?startDate=2026-01-01&endDate=2026-12-31&userId='+A);check('authenticated report yields PDF',report.headers.get('content-type').includes('pdf')&&(await report.arrayBuffer()).byteLength>100);
mount('/csv');await wait(()=>document.querySelector('input[type=file]'));const input=document.querySelector('input[type=file]');Object.defineProperty(input,'files',{value:[new File(['court,matterno\nBrowserCsvCourt,123'],'synthetic.csv',{type:'text/csv'})]});input.dispatchEvent(new Event('change',{bubbles:true}));await wait(()=>document.body.textContent.includes('BrowserCsvCourt'));check('real CSV upload/list uses session owner and no manual multipart boundary',!document.body.textContent.includes('OtherPrivateCsv'));
sessionStorage.removeItem('tnt_draft_session');let denied=false;try{await tenantFetch('/api/cases/user/'+A)}catch{denied=true}check('restored workflow client fails closed after logout',denied);
mount('/maintenance');await wait(()=>document.body.textContent.includes('Payment book temporarily unavailable'));check('paused workflow has explicit data-preserving notice',document.body.textContent.includes('Existing records are retained'));
}catch(e){check('completed: '+e.message,false)}document.body.innerHTML='<pre id="verification-result"></pre>';document.getElementById('verification-result').textContent=JSON.stringify(results)})();
